def monicPolynomial {n : ℕ} (a : Fin n → O) : Polynomial (BaseField O) :=
  Polynomial.X^n + ∑ i : Fin n,
    Polynomial.C (algebraMap O (BaseField O) (a i)) * Polynomial.X^i.val

noncomputable def projectiveDensity (n : ℕ) (σ : FactorType) : ℝ≥0∞ :=
  coefficientMeasure O (n+1) {a | primitive O a ∧ HasBinaryType O a σ} /
    coefficientMeasure O (n+1) {a | primitive O a}

def IsEtaleForm {n : ℕ} (a : Fin (n + 1) → O) : Prop :=
  affinePolynomial O a ≠ 0 ∧ n - (affinePolynomial O a).natDegree ≤ 1 ∧
    (affinePolynomial O a).Separable

def surfaceStateSet (S : SurfaceData O R) (s : State) : Set (Ideal R) :=
  {J | (∃ f : R, J = Ideal.span {f}) ∧ s.Valid ∧
    match s with
    | .single a c => S.a = a ∧ S.b = 0 ∧ idealContact R J S.t = c
    | .crossing a b c h => S.a = a ∧ S.b = b ∧
      idealContact R J S.t = c ∧ idealContact R J S.x = h}

theorem concrete_member_terminal_type (m : ConcreteMember) (a : ℕ) (hs : m.s = State.single a 1)
    (J : Ideal m.R) (hJ : J ∈ m.toMeasured.stateSet) :
    HasAlgebraType m.O (m.R ⧸ J) {(a, 1)}

private theorem crossing_left_one_law (a b h : ℕ) (ha : 0 < a) (hb : 0 < b) (hh : 0 < h) (q : ℚ)
    (hq : 1 < q) (σ : FactorType) :
    coeffAt q (stateLaw (.crossing a b 1 h)) σ = if σ = {(a+h*b, 1)} then 1 else 0

private theorem crossing_right_one_law (a b c : ℕ) (ha : 0 < a) (hb : 0 < b) (hc : 0 < c) (q : ℚ)
    (hq : 1 < q) (σ : FactorType) :
    coeffAt q (stateLaw (.crossing a b c 1)) σ = if σ = {(c*a+b, 1)} then 1 else 0

def crossingResidueIdeals (k : Type) [CommRing k] (a b c h : ℕ) :=
  {I : Ideal (SpecialFiber k a b) // ∃ f, I=Ideal.span {f} ∧
    contact f (fiberT k a b)=c ∧ contact f (fiberX k a b)=h}

def idealChartSigma [MeasurableSpace O] (pi : O) : MeasurableSpace (Ideal R) :=
  MeasurableSpace.generateFrom
    {T : Set (Ideal R) | ∃ (n : ℕ) (f : R) (b : Fin n → R) (S : Set (Fin n → O)),
      IsDivisionChart O R pi f b ∧ MeasurableSet S ∧ T = coordinateIdeal pi f b '' S}

def otherChildren {n : ℕ} (a : ℕ) (m : Pattern n) : List (ℕ × State) :=
  (Finset.univ : Finset (Fin n × Fin n)).toList.flatMap fun ij =>
    List.replicate (m ij).val (ij.1.val+1, .single a (ij.2.val+1))

def pointCount (δ : ℕ) : Expr :=
  .mul (.const (1/(δ:ℚ))) (Expr.sum ((Nat.divisors δ).toList.map fun j =>
    .mul (.const ((ArithmeticFunction.moebius j : ℤ) : ℚ)) (.pow .var (δ/j))))

theorem card_pow_eq_sum_irreducible_degrees (k : Type) [Field k] [Finite k] (m : ℕ) (hm : 0 < m) :
    (Nat.card k) ^ m = ∑ d ∈ m.divisors, d *
    Nat.card {g : Polynomial k // g.Monic ∧ Irreducible g ∧ g.natDegree = d}

def adamsCoef (δ : ℕ) : Coef →+* Coef :=
  (AddMonoidAlgebra.mapDomainRingHom (RatFunc ℚ) (scaleTypeHom δ)).comp
    (AddMonoidAlgebra.mapRingHom FactorType (adamsRat δ))

private theorem gaussPhi_dilate_recipSer_clusterSer (a : ℕ) (ha : 0 < a) :
    gaussPhi (dilate (recipSer (clusterSer a))) =
      qact (qdagger (crossingQ a a)) (dilate (recipSer (eulerSer 0 a)))

private theorem crossing_two_two_law_at_two (σ : FactorType) :
    coeffAt 2 (stateLaw (.crossing 1 1 2 2)) σ = (if σ = {(4,1)} then 1/3 else 0) +
      (if σ = {(2,2)} then 7/12 else 0) + (if σ = (2,1) ::ₘ {(2,1)} then 1/12 else 0)
